static void ledlight_unit_eventqueue_init(ledlight_unit_eventqueue * eq, ledlight_unit_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer ledlight_unit_eventqueue_size(ledlight_unit_eventqueue * eq)
{
	return eq->size;
}

static ledlight_unit_event ledlight_unit_eventqueue_pop(ledlight_unit_eventqueue * eq)
{
	ledlight_unit_event event;
	if(ledlight_unit_eventqueue_size(eq) <= 0) {
		ledlight_unit_event_init(&event, LEDLight_Unit_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean ledlight_unit_eventqueue_push(ledlight_unit_eventqueue * eq, ledlight_unit_event ev)
{
	if(ledlight_unit_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void ledlight_unit_event_init(ledlight_unit_event * ev, LEDLight_UnitEventID name)
{
	ev->name = name;
}

static void lEDLight_Unit_add_event_to_queue(ledlight_unit_eventqueue * eq, LEDLight_UnitEventID name)
{
	ledlight_unit_event event;
	ledlight_unit_event_init(&event, name);
	ledlight_unit_eventqueue_push(eq, event);
}

static sc_boolean lEDLight_Unit_dispatch_event(LEDLight_Unit* handle, const ledlight_unit_event * event) {
	switch(event->name) {
		case LEDLight_Unit_device_on:
		{
			handle->ifaceDevice.on_raised = bool_true;
			return bool_true;
		}
		case LEDLight_Unit_device_off:
		{
			handle->ifaceDevice.off_raised = bool_true;
			return bool_true;
		}
		case LEDLight_Unit_Brightness_up:
		{
			handle->ifaceBrightness.up_raised = bool_true;
			return bool_true;
		}
		case LEDLight_Unit_Brightness_down:
		{
			handle->ifaceBrightness.down_raised = bool_true;
			return bool_true;
		}
		case LEDLight_Unit_LEDLight_Unit__LED_Light_Unit___On___Bulb_Status__Bulb_on_standby_time_event_0:
		{
			handle->timeEvents.lEDLight_Unit__LED_Light_Unit___On___Bulb_Status__Bulb_on_standby_tev0_raised = bool_true;
			return bool_true;
		}
		case LEDLight_Unit_LEDLight_Unit__LED_Light_Unit___On___Bulb_Status__Bulb_on_time_event_0:
		{
			handle->timeEvents.lEDLight_Unit__LED_Light_Unit___On___Bulb_Status__Bulb_on_tev0_raised = bool_true;
			return bool_true;
		}
		default:
			return bool_false;
	}
}

static ledlight_unit_event lEDLight_Unit_get_next_event(LEDLight_Unit* handle)
{
	ledlight_unit_event next_event;
	ledlight_unit_event_init(&next_event, LEDLight_Unit_invalid_event);
	if(ledlight_unit_eventqueue_size(&(handle->in_event_queue)) > 0) {
		next_event = ledlight_unit_eventqueue_pop(&(handle->in_event_queue));
	}
	return next_event;
}

static sc_boolean lEDLight_Unit_dispatch_next_event(LEDLight_Unit* handle)
{
	ledlight_unit_event nextEvent;
	nextEvent = lEDLight_Unit_get_next_event(handle);
	return lEDLight_Unit_dispatch_event(handle, &nextEvent);
}

static LEDLight_UnitEventID lEDLight_Unit_get_timed_event_name(LEDLight_Unit* handle, sc_eventid evid)
{
	if(evid == &handle->timeEvents.lEDLight_Unit__LED_Light_Unit___On___Bulb_Status__Bulb_on_standby_tev0_raised) {
		return LEDLight_Unit_LEDLight_Unit__LED_Light_Unit___On___Bulb_Status__Bulb_on_standby_time_event_0;
	}
	if(evid == &handle->timeEvents.lEDLight_Unit__LED_Light_Unit___On___Bulb_Status__Bulb_on_tev0_raised) {
		return LEDLight_Unit_LEDLight_Unit__LED_Light_Unit___On___Bulb_Status__Bulb_on_time_event_0;
	}
	return LEDLight_Unit_invalid_event;
}

